      tenQuestionCheck: MCQ_ITEMS.map((q, i) => ({ id: 'Q' + (i + 1), prompt: q.q, context: q.ctx, options: q.opts.map((o, k) => LET[k] + '. ' + o), answerKey: LET[q.ok], explanation: q.why, speakingExtension: q.ext, spokenExplanation: q.sp })),
