      wordBank: { pronouns: WB.pron, be: WB.be, phrases: WB.words, rules: { beByPronoun: WB_BE, personNouns: WB_PERSON_NOUN, thingNouns: WB_THING_NOUN, pluralNouns: WB_PLURAL_NOUN, feelings: WB_FEELING, places: WB_PLACE }, feedbackCodes: ['empty', 'start', 'need-be', 'not-be', 'agreement', 'need-end', 'too-long', 'unknown-end', 'plural-subject', 'singular-subject', 'thing-noun', 'person-noun', 'ok'] },
      ipa: { notation: 'Uploaded Fluent English Sound Chart notation; agrees with current Oxford Learner’s (OALD) NAmE for GOAT /əʊ/. Oxford Advanced American /oʊ/ is a different transcription standard and is not mixed in.', entries: st.entries, sourceVerifiedEntries: st.verified, handEnteredEntries: st.entries - st.verified, verifiedWords: Object.fromEntries(Object.keys(IPA.STATUS).map((w) => [w, { ipa: IPA.D[w], source: IPA.SOURCES[w] }])), sentenceLinesAreAssembledWordByWord: true, audioListeningVerified: false },
      voices: { narrator: 'default/chosen browser voice', maleCharacters: ['alex', 'daniel', 'omar', 'ken'], femaleCharacters: ['maya', 'sofia', 'lena', 'rosa'], note: 'Gender-matching is a name-based guess from installed voices (or a small pitch shift); not verified by listening.' },
      activities,
